def lesson(num):
    """(title, groups) for vcard; 4-tuple items get an empty collocation list."""
    for n, t, gs in VOCAB:
        if n == num:
            return t, [(g, [tuple(w) if len(w) == 5 else tuple(w) + ([],) for w in ws]) for g, ws in gs]
    raise KeyError(num)
